input.content:
import { Post } from './types';

/**
 * A page flowing through the plugin pipeline.
 *
 * The core engine reads each Markdown file and creates an initial `Page` whose
 * `content` field still holds the raw source (including frontmatter). The
 * built-in `MarkdownPlugin` parses it and rewrites `content` to the stripped
 * Markdown body while filling in the metadata and `html`. The built-in
 * `TemplatePlugin` then renders the final full-page HTML into `rendered`.
 */
export interface Page extends Post {
  /**
   * The final, full-page HTML produced by the template plugin. The engine
   * writes this value to disk. It is not part of the public `Post` type
   * returned by `buildSite`.
   */
  rendered?: string;
}

export type MaybePromise<T> = T | Promise<T>;

/**
 * The lifecycle of a plugin. Each hook is optional.
 *
 * - `onStart()`      runs once before anything else.
 * - `beforeBuild()`  runs once after `onStart` and before any page is read.
 * - `onFile(page)`   runs once per page, in pipeline order.
 * - `afterBuild()`   runs once after every page has been processed and written.
 * - `onEnd()`        runs once at the very end of the build.
 */
export interface Plugin {
  name?: string;
  onStart?(): MaybePromise<void>;
  beforeBuild?(): MaybePromise<void>;
  onFile?(page: Page): MaybePromise<void>;
  afterBuild?(): MaybePromise<void>;
  onEnd?(): MaybePromise<void>;
}

/**
 * Runs every plugin's hook for a given lifecycle stage, preserving plugin
 * order. Hooks may be synchronous or return a Promise.
 */
export class PluginPipeline {
  constructor(public readonly plugins: Plugin[] = []) {}

  async onStart(): Promise<void> {
    for (const plugin of this.plugins) {
      await plugin.onStart?.();
    }
  }

  async beforeBuild(): Promise<void> {
    for (const plugin of this.plugins) {
      await plugin.beforeBuild?.();
    }
  }

  async onFile(page: Page): Promise<void> {
    for (const plugin of this.plugins) {
      await plugin.onFile?.(page);
    }
  }

  async afterBuild(): Promise<void> {
    for (const plugin of this.plugins) {
      await plugin.afterBuild?.();
    }
  }

  async onEnd(): Promise<void> {
    for (const plugin of this.plugins) {
      await plugin.onEnd?.();
    }
  }
}

import { PageContext } from './templates';
import { Post } from './types';

export function escapeHtml(value: string): string {
  return String(value).replace(/[&<>"']/g, (ch) => {
    switch (ch) {
      case '&':
        return '&amp;';
      case '<':
        return '&lt;';
      case '>':
        return '&gt;';
      case '"':
        return '&quot;';
      case "'":
        return '&#39;';
      default:
        return ch;
    }
  });
}

export function renderIndex(posts: Post[]): string {
  const items = posts
    .map((post) => {
      const href = `${post.slug}.html`;
      const title = escapeHtml(post.title || post.slug);
      const date = post.date
        ? `<time datetime="${escapeHtml(post.date)}">${escapeHtml(post.date)}</time>`
        : '';
      const tags = post.tags.length
        ? `<span class="tags">${post.tags.map(escapeHtml).join(', ')}</span>`
        : '';
      const meta = [date, tags].filter(Boolean).join(' ');
      return `<li><a href="${href}">${title}</a>${meta ? ` — ${meta}` : ''}</li>`;
    })
    .join('\n    ');

  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Site Index</title>
</head>
<body>
  <header><h1>Site Index</h1></header>
  <main>
    <ul>
    ${items || '<li>(no pages)</li>'}
    </ul>
  </main>
</body>
</html>
`;
}

export function renderPage(post: Post): string {
  const title = escapeHtml(post.title || post.slug);
  const date = post.date
    ? `<time datetime="${escapeHtml(post.date)}">${escapeHtml(post.date)}</time>`
    : '';
  const tags = post.tags.length
    ? `<p class="tags">Tags: ${post.tags.map(escapeHtml).join(', ')}</p>`
    : '';

  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${title}</title>
</head>
<body>
  <header>
    <a href="index.html">← Index</a>
    <h1>${title}</h1>
    ${date ? `<p>${date}</p>` : ''}
    ${tags}
  </header>
  <main>
${post.html}
  </main>
</body>
</html>
`;
}

export function pageToContext(post: Post): PageContext {
  return {
    title: post.title,
    date: post.date,
    tags: post.tags,
    slug: post.slug,
    content: post.content,
    body: post.html,
  };
}

import { parseMarkdown } from '../markdown';
import { Page, Plugin } from '../plugin';

/**
 * Built-in plugin that parses Markdown documents.
 *
 * The engine creates each `Page` with the raw file source in `content`. This
 * plugin parses the frontmatter, rewrites `content` to the stripped Markdown
 * body and fills `html` with the rendered body HTML.
 */
export class MarkdownPlugin implements Plugin {
  name = 'markdown';

  onFile(page: Page): void {
    const { meta, content, html } = parseMarkdown(page.content);

    page.title = meta.title || page.slug;
    page.date = meta.date;
    page.tags = meta.tags;
    page.template = meta.template;
    page.content = content;
    page.html = html;
  }
}

import { pageToContext, renderPage } from '../render';
import { Page, Plugin } from '../plugin';
import { TemplateEngine } from '../templates';

/**
 * Built-in plugin that renders each page through a Handlebars template.
 *
 * It prefers the layout named by the page's `template` metadata, falling back
 * to the `default` layout, and finally to the built-in HTML page renderer when
 * no layout matches. The final full-page HTML is stored in `page.rendered`.
 */
export class TemplatePlugin implements Plugin {
  name = 'template';

  private engine: TemplateEngine;

  constructor(templatesDir: string) {
    this.engine = new TemplateEngine(templatesDir);
  }

  onFile(page: Page): void {
    const rendered = this.engine.render(page.template, pageToContext(page));
    page.rendered = rendered ?? renderPage(page);
  }
}

import { Plugin } from '../plugin';
import { ServeHandle, ServeOptions, startServer } from '../serve';

/**
 * Built-in plugin that starts the development server.
 *
 * `onStart` builds the site, serves it over HTTP and begins watching the
 * content/templates directories for changes. `onEnd` tears the server down.
 */
export class DevServerPlugin implements Plugin {
  name = 'dev-server';

  private handle?: ServeHandle;

  constructor(private options: ServeOptions = {}) {}

  async onStart(): Promise<void> {
    this.handle = await startServer(this.options);
  }

  async onEnd(): Promise<void> {
    if (this.handle) {
      await this.handle.close();
      this.handle = undefined;
    }
  }

  get address(): string | undefined {
    return this.handle?.address;
  }

  get port(): number | undefined {
    return this.handle?.port;
  }
}

export { MarkdownPlugin } from './markdown-plugin';
export { TemplatePlugin } from './template-plugin';
export { DevServerPlugin } from './dev-server-plugin';

import fs from 'fs';
import path from 'path';

import { Plugin } from './plugin';

/**
 * The shape of a `ssg.config.ts` file. It may export the config directly, as a
 * `default` export, or as a function returning the config.
 */
export interface SsgConfig {
  plugins?: Plugin[];
}

const CONFIG_FILENAMES = ['ssg.config.ts', 'ssg.config.js', 'ssg.config.mjs', 'ssg.config.cjs'];

let tsHookInstalled = false;

function compileTypeScript(source: string): string {
  const ts = require('typescript');
  return ts.transpileModule(source, {
    compilerOptions: {
      module: ts.ModuleKind.CommonJS,
      target: ts.ScriptTarget.ES2020,
      esModuleInterop: true,
      moduleResolution: ts.ModuleResolutionKind.NodeJs,
    },
  }).outputText;
}

/**
 * Registers a `require` extension for `.ts` files so that `ssg.config.ts` and
 * its plugin modules (which live in `./plugins/*.ts`) can be loaded at runtime.
 * No-op when TypeScript support is already registered (ts-node, ts-jest, ...).
 */
export function installTypeScriptRequireHook(): void {
  if (tsHookInstalled) {
    return;
  }
  tsHookInstalled = true;

  const extensions = (require as unknown as {
    extensions: Record<string, (mod: NodeModule & { _compile: (code: string, filename: string) => void }, filename: string) => void>;
  }).extensions;

  if (typeof extensions['.ts'] === 'function') {
    return;
  }

  extensions['.ts'] = (mod, filename) => {
    const source = fs.readFileSync(filename, 'utf-8');
    mod._compile(compileTypeScript(source), filename);
  };
}

function findConfigFile(dir: string): string | undefined {
  for (const name of CONFIG_FILENAMES) {
    const candidate = path.join(dir, name);
    if (fs.existsSync(candidate)) {
      return candidate;
    }
  }
  return undefined;
}

function unwrapDefault(loaded: unknown): unknown {
  if (loaded && typeof loaded === 'object' && 'default' in (loaded as Record<string, unknown>)) {
    return (loaded as Record<string, unknown>).default;
  }
  return loaded;
}

/**
 * Loads and evaluates a `ssg.config.ts` (or `.js`/`.mjs`/`.cjs`) file from the
 * given directory, returning the exported configuration object.
 */
export function loadConfig(dir: string = process.cwd()): SsgConfig {
  const filePath = findConfigFile(dir);
  if (!filePath) {
    return {};
  }

  installTypeScriptRequireHook();

  const resolved = path.resolve(filePath);
  delete require.cache[resolved];

  let config = unwrapDefault(require(resolved));
  if (typeof config === 'function') {
    config = config();
  }
  if (config == null || typeof config !== 'object') {
    return {};
  }
  return config as SsgConfig;
}

/**
 * Loads the plugin instances declared in the `ssg.config.ts` file located in
 * the given directory.
 */
export function loadPlugins(dir: string = process.cwd()): Plugin[] {
  const config = loadConfig(dir);
  const plugins = config.plugins ?? [];
  return plugins.filter((plugin): plugin is Plugin => !!plugin);
}

import fs from 'fs';
import path from 'path';

import { loadPlugins } from './config';
import { Page, Plugin } from './plugin';
import { MarkdownPlugin } from './plugins/markdown-plugin';
import { TemplatePlugin } from './plugins/template-plugin';
import { renderIndex } from './render';
import { Post } from './types';

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
  templatesDir?: string;
  /** Extra plugins appended after the built-in plugins. */
  plugins?: Plugin[];
  /** Directory searched for `ssg.config.ts`. Defaults to `process.cwd()`. */
  configDir?: string;
}

export interface BuildResult {
  posts: Post[];
  filesWritten: string[];
  outputDir: string;
}

function listMarkdownFiles(dir: string): string[] {
  const files: string[] = [];
  if (!fs.existsSync(dir)) {
    return files;
  }
  for (const entry of fs.readdirSync(dir)) {
    const fullPath = path.join(dir, entry);
    const stat = fs.statSync(fullPath);
    if (stat.isDirectory()) {
      files.push(...listMarkdownFiles(fullPath));
    } else if (stat.isFile() && /\.md$/i.test(entry)) {
      files.push(fullPath);
    }
  }
  return files;
}

function slugForFile(filePath: string, contentDir: string): string {
  const relative = path.relative(contentDir, filePath);
  const withoutExtension = relative.replace(/\.md$/i, '');
  return withoutExtension.split(path.sep).join('/');
}

function sortPosts(posts: Post[]): void {
  posts.sort((a, b) => {
    const dateA = a.date ? Date.parse(a.date) : NaN;
    const dateB = b.date ? Date.parse(b.date) : NaN;
    if (!Number.isNaN(dateA) && !Number.isNaN(dateB) && dateA !== dateB) {
      return dateB - dateA;
    }
    if (Number.isNaN(dateA) && !Number.isNaN(dateB)) {
      return 1;
    }
    if (!Number.isNaN(dateA) && Number.isNaN(dateB)) {
      return -1;
    }
    return a.title.localeCompare(b.title);
  });
}

type LifecycleHook = 'onStart' | 'beforeBuild' | 'afterBuild' | 'onEnd';

function runHooksSync(plugins: Plugin[], method: LifecycleHook): void {
  for (const plugin of plugins) {
    const hook = plugin[method] as (() => unknown) | undefined;
    if (typeof hook !== 'function') {
      continue;
    }
    const result = hook.call(plugin);
    if (result != null && typeof (result as Promise<unknown>).then === 'function') {
      throw new Error(
        `Plugin "${plugin.name ?? 'unnamed'}" returned a Promise from "${method}". ` +
          'Asynchronous plugin hooks are not supported by the synchronous build pipeline.',
      );
    }
  }
}

function runFileHooksSync(plugins: Plugin[], page: Page): void {
  for (const plugin of plugins) {
    const hook = plugin.onFile as ((page: Page) => unknown) | undefined;
    if (typeof hook !== 'function') {
      continue;
    }
    const result = hook.call(plugin, page);
    if (result != null && typeof (result as Promise<unknown>).then === 'function') {
      throw new Error(
        `Plugin "${plugin.name ?? 'unnamed'}" returned a Promise from "onFile". ` +
          'Asynchronous plugin hooks are not supported by the synchronous build pipeline.',
      );
    }
  }
}

/**
 * Build a static site by running the plugin pipeline.
 *
 * The built-in `MarkdownPlugin` and `TemplatePlugin` always run first (in that
 * order), followed by any plugins passed via `options.plugins` and any plugins
 * declared in the project's `ssg.config.ts`.
 */
export function buildSite(options: BuildOptions): BuildResult {
  const { contentDir, outputDir } = options;
  const templatesDir = options.templatesDir ?? path.join(process.cwd(), 'templates');
  const configDir = options.configDir ?? process.cwd();

  const plugins: Plugin[] = [
    new MarkdownPlugin(),
    new TemplatePlugin(templatesDir),
    ...(options.plugins ?? []),
    ...loadPlugins(configDir),
  ];

  runHooksSync(plugins, 'onStart');
  runHooksSync(plugins, 'beforeBuild');

  const markdownFiles = listMarkdownFiles(contentDir);
  const pages: Page[] = markdownFiles.map((filePath) => {
    const slug = slugForFile(filePath, contentDir);
    const source = fs.readFileSync(filePath, 'utf-8');
    return {
      slug,
      title: '',
      date: undefined,
      tags: [],
      template: undefined,
      content: source,
      html: '',
    };
  });

  for (const page of pages) {
    runFileHooksSync(plugins, page);
  }

  sortPosts(pages);

  fs.mkdirSync(outputDir, { recursive: true });

  const filesWritten: string[] = [];

  const indexPath = path.join(outputDir, 'index.html');
  fs.writeFileSync(indexPath, renderIndex(pages));
  filesWritten.push(indexPath);

  for (const page of pages) {
    const pagePath = path.join(outputDir, `${page.slug}.html`);
    fs.mkdirSync(path.dirname(pagePath), { recursive: true });
    fs.writeFileSync(pagePath, page.rendered ?? '');
    filesWritten.push(pagePath);
  }

  runHooksSync(plugins, 'afterBuild');
  runHooksSync(plugins, 'onEnd');

  const posts: Post[] = pages.map((page) => ({
    slug: page.slug,
    title: page.title,
    date: page.date,
    tags: page.tags,
    template: page.template,
    content: page.content,
    html: page.html,
  }));

  return { posts, filesWritten, outputDir };
}

export { buildSite } from './site';
export type { BuildOptions, BuildResult } from './site';
export { parseMarkdown, renderMarkdown, normalizeTags } from './markdown';
export { TemplateEngine } from './templates';
export type { PageContext } from './templates';
export type { PageMeta, ParsedMarkdown, Post } from './types';
export { startServer, injectLiveReloadScript, LIVE_RELOAD_PATH } from './serve';
export type { ServeOptions, ServeHandle } from './serve';

export type { Plugin, Page, MaybePromise } from './plugin';
export { PluginPipeline } from './plugin';
export { MarkdownPlugin, TemplatePlugin, DevServerPlugin } from './plugins';
export { loadConfig, loadPlugins, installTypeScriptRequireHook } from './config';
export type { SsgConfig } from './config';

